INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 96, 'proposito', 'Gestionar la implementación de las iniciativas de los Programas de Desarrollo con Enfoque Territorial –PDET-mediante su articulación a la planeación municipal y a la oferta de servicios de índole nacional y regional, de la cooperación internacional y los entes privados, de acuerdo con los procedimientos establecidos y la normatividad vigente.', 140 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=96 AND seccion='proposito');  -- FICHA 61
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 96, 'funciones', '["Elaborar y actualizar la caracterización de las iniciativas de los PDET y los Planes de Acción de Transformación Territorial –PATR- de acuerdo con los lineamientos impartidos en la entidad y la normatividad vigente.", "Identificar y gestionar la oferta externa de servicios para la ejecución de la inversión PDET proporcionada por las entidades nacionales y regionales, la cooperación internacional y los entes privados, de acuerdo con la distribución de competencias de los niveles de gobierno y lo dispuesto en la normatividad aplicable.", "Proponer convenios y asociaciones de naturaleza público privadas, o público estatal, dirigidas a la implementación de las iniciativas PDET, de acuerdo con las competencias del municipio y lo previsto en la normatividad.", "Adelantar las actividades que aseguren la comunicación e interlocución de la Alcaldía con la Agencia de Renovación del Territorio (ART), las entidades del orden nacional, departamental y regional, y lo órganos de control, para los reportes de información y la participación en mesas interinstitucionales, eventos de capacitación, actividades y/o comités técnicos internos o externos, relacionados con la implementación de las iniciativas PDET, de acuerdo con los lineamientos de la entidad.", "Vincular las iniciativas PDET a los instrumentos de planeación institucional, ordenamiento territorial, presupuestal y contractual, en concordancia con los procesos de la entidad y lo dispuesto en la normatividad vigente.", "Gestionar con las dependencias de la entidad las acciones para la formulación, estructuración, viabilidad, programación, ejecución, seguimiento, operación y evaluación de los proyectos de inversión PDET, de acuerdo con las metodologías del gobierno nacional y regional, y lo dispuesto en la normatividad.", "Rendir los informes que requiera la administración, de acuerdo con los lineamientos de la entidad y las normas aplicables.", "Apoyar el diseño y la actualización de los procesos y procedimientos del área de gestión de proyectos PDET, en consonancia con los lineamientos de la entidad.", "Mantener actualizada la información en los sistemas, aplicativos y otros medios tecnológicos de su competencia, de acuerdo con estándares de seguridad y privacidad de la información.", "Atender a los líderes del grupo motor en el proceso de veeduría, seguimiento y control de los proyectos que se deriven de las iniciativas PDET y que sean formulados y ejecutados tanto a nivel municipal como a nivel regional.", "Rendir periódicamente informes al Secretario, sobre las actividades de la dependencia para su análisis, evaluación y toma de decisiones.", "Realizar labores de apoyo a los diferentes grupos de trabajo dentro de la Secretaría, especialmente en labores de rendición de cuentas.", "Adoptar, las acciones necesarias para garantizar el sistema de gestión de la calidad y el control interno dentro de la dependencia.", "Y las demás asignadas por su superior inmediatos."]', 141 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=96 AND seccion='funciones');  -- FICHA 61
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 96, 'contribuciones', '["Lo proyectos PDET del municipio se ajustan a los requerimientos técnicos establecidos.", "Rendición de informes de acuerdo con la normatividad vigente."]', 142 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=96 AND seccion='contribuciones');  -- FICHA 61
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 96, 'conocimientos', '["Metodologías de formulación, evaluación, seguimiento y ejecución de planes, programas y proyectos.", "Finanzas públicas territoriales.", "Contratación estatal.", "Estructura y administración del Estado.", "Estructura organizacional de la entidad.", "Planeación estratégica.", "Formulación, aplicación e interpretación de indicadores de gestión.", "Redacción y proyección de documentos técnicos."]', 143 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=96 AND seccion='conocimientos');  -- FICHA 61
