INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 137, 'proposito', 'Apoyar en la preparación de la información financiera de acuerdo a las disposiciones legales vigentes para fortalecer la calidad de la información de la tesorería de manera que sirva de base para la toma de decisiones administrativas. De igual manera, mantener un registro actualizado sobre bancos y fondos, a fin de conocer saldos actualizados para la toma de decisiones.', 140 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=137 AND seccion='proposito');  -- FICHA 53
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 137, 'funciones', '["Efectuar los diferentes registros requeridos para la obtención de los informes contables y financieros, realizar recaudos de ingresos y cuadrar caja diariamente.", "Mantener actualizada la información contable.", "Llevar correctamente y al orden del día los libros de contabilidad, así como la ejecución de los demás trabajos contables de la dependencia.", "Coadyuvar en la elaboración del Balance General y de los Estados Financieros, para asegurar su correcta consolidación.", "Registrar y codificar contablemente de acuerdo al Plan General de Contabilidad Pública, los movimientos que genere la administración, con el fin de obtener los estados contables.", "Emitir los reportes contables y financieros necesarios, para permitirle al ordenador del gasto y al pagador, tomar decisiones oportunamente.", "Ingresar al sistema todo movimiento que se genere desde la Tesorería, Presupuesto, Nómina y Almacén por intermedio de los diferentes documentos soporte de las actividades.", "Efectuar las conciliaciones de todas las cuentas bancarias que posee el Municipio.", "Entrega de informes comparativos de las conciliaciones con respecto a los bancos.", "Coadyuvar en la legalización de los rendimientos financieros que generen las cuentas de ahorro y legalización de notas débito por cobros de comisiones de consignaciones nacionales.", "Realizar labores de apoyo a los procesos administrativos que se ejecuten en la Secretaría de conformidad con los planes, programas y proyectos establecidos, velando porque los reportes de ingresos recaudados a través de las entidades financieras, se realicen de manera oportuna y los mismos se reflejen en la ejecución presupuestal del municipio.", "Ejecutar los planes, programas y proyectos asignados por la Dirección Financiera y la Tesorería de Rentas Municipales, para lograr el fortalecimiento de los sistemas de información municipal.", "Ingresar al sistema de tesorería las órdenes de pago canceladas, su valor y los datos con relación al banco, también, las consignaciones efectuadas.", "Modificar y actualizar los datos solicitados solamente por las personas autorizadas, para asegurar confiabilidad en la información requerida.", "Operar los diferentes programas instalados para prestar eficientemente los servicios a cargo de la Dirección financiera y Tesorería y garantizar su actualización y adecuado funcionamiento.", "Reportar oportunamente los informes financieros, tales como: boletín de caja, ejecución presupuestal de ingresos y egresos, y demás soportes, entre otros, para la toma de decisiones y rendición de cuentas oportunas.", "Pasar a la sección de contabilidad todo movimiento que se efectúe tanto de ingresos como egresos en su respectiva planilla de resumen.", "Desglosar las diversas deducciones y entregar oportunamente los informes para sus respectivos pagos.", "Elaborar, examinar y revisar la documentación que se procesa con el fin de lograr el funcionamiento regular de la dependencia.", "Preparar y entregar los certificados que se autoricen, a los proveedores y contratistas. Presentar ante los entes gubernamentales y/o entidades particulares y privadas los informes solicitados.", "Adoptar, las acciones necesarias para garantizar el sistema de gestión de la calidad y el control interno dentro de la dependencia.", "Y las demás que sean asignados por su jefe inmediato."]', 141 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=137 AND seccion='funciones');  -- FICHA 53
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 137, 'contribuciones', '["Asegurar la precisión y oportunidad en el registro de los diferentes movimientos contables y financieros, garantizando la actualización diaria de la información y la conciliación para una adecuada toma de decisiones.", "Efectuar las conciliaciones bancarias y presentar informes comparativos que permitan un adecuado seguimiento de los recursos, Ingresar y validar la información financiera en los sistemas administrativos, asegurando que los ingresos y egresos de la entidad se reflejen oportunamente en la ejecución presupuestal del municipio.", "Adoptar y ejecutar acciones para fortalecer el sistema de gestión de la calidad y el control interno dentro de la dependencia, asegurando que los procesos contables cumplan con el Plan General de Contabilidad Pública y las normativas vigentes."]', 142 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=137 AND seccion='contribuciones');  -- FICHA 53
