INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 138, 'proposito', 'Velar por el adecuado manejo presupuestal en cada una de sus etapas (elaboración, aprobación, liquidación y ejecución) se ajuste a la normatividad legal vigente y en especial a lo señalado en el estatuto orgánico de presupuesto.', 140 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=138 AND seccion='proposito');  -- FICHA 52
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 138, 'funciones', '["Proyectar, y controlar los certificados de disponibilidad presupuestal y manejar el registro presupuestal.", "Efectuar oportunamente los registros requeridos, para la generación de informes presupuéstales.", "Velar por la actualización de la información presupuestal.", "Realizar las actividades requeridas para un adecuado manejo del presupuesto.", "Coadyuvar en la elaboración del proyecto de presupuesto, para asegurar su correcta ejecución.", "Participar en la elaboración de planes, programas y proyectos de inversión Pública Municipal.", "Coadyuvar en los estudios y seguimientos necesarios para la elaboración del Presupuesto Municipal.", "Opinar sobre los traslados presupuéstales necesarios, según recursos disponibles por cada artículo presupuestal, para garantizar el cumplimiento oportuno de planes, programas y proyectos.", "Realizar proyecciones que permitan conocer el comportamiento de los ingresos y egresos para el manejo adecuado de los recursos.", "Efectuar las adiciones a que haya lugar y según la destinación, para garantizar el cumplimiento oportuno de planes, programas y proyectos.", "Desarrollar todas las actividades necesarias para el registro y rendición de cuentas de la deuda pública, el ingreso de la información pertinente y la elaboración de informes para las entidades gubernamentales, organismos de control o de orden privado.", "Proyectar los certificados de la disponibilidad y reserva presupuestal, solicitadas por los funcionarios competentes, para garantizar la financiación de los proyectos.", "Elaborar el proyecto de Decreto de Liquidación del presupuesto Elaborar los proyectos de actos administrativos de constitución de reservas y cuentas por pagar al 31 de diciembre de cada vigencia.", "Apoyo a la labor administrativa de la dependencia.", "Proyectar actos administrativos requeridos en el manejo presupuestal municipal y de conformidad con las autorizaciones del COMFIS.", "Revisar los soportes de los diferentes comprobantes que se acrediten para el pago de las obligaciones a cargo del municipio y elaborar los comprobantes de pago de aquellos que se ajusten a los requerimientos exigidos.", "Ejercer funciones como secretaria del COMFIS. 19.", "Adoptar, las acciones necesarias para garantizar el sistema de gestión de la    calidad y el control interno dentro de la dependencia.", "Y las demás que sean asignados por su jefe inmediato de acuerdo a la necesidad del servicio."]', 141 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=138 AND seccion='funciones');  -- FICHA 52
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 138, 'contribuciones', '["Se consolida y se prepara el anteproyecto anual de ingresos y gastos del Municipio en coordinación con el secretario de Hacienda, sus asesores y los secretarios de Despacho.", "Se expiden, autorizan y controlan los certificados de disponibilidad presupuestal.", "Se elaboran las reservas presupuéstales, de conformidad con las normas legales vigentes."]', 142 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=138 AND seccion='contribuciones');  -- FICHA 52
