INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 139, 'proposito', 'Realizar una adecuada administración y conservación de la información catastral del municipio la cual contribuya de manera efectiva a que se cuente con una base de datos en materia predial, ajustada a la realidad del ente municipal.', 140 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=139 AND seccion='proposito');  -- FICHA 66
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 139, 'funciones', '["Delimitar sobre fotos, áreas o planchas de linderos urbanos y rurales o compilar sus atributos catastrales.", "Registrar las mutaciones e inscribirlas en las hojas codificadas, para actualizar la ficha predial acorde con los procedimientos establecidos por la entidad.", "Elaborar, relacionar y actualizar las fichas resultantes por ventas parciales, reloteos, particiones y englobes, tanto en la zona urbana como rural, para realizar posteriormente el levantamiento predial.", "Revisar las escrituras y documentos públicos entregados por los usuarios, para verificar que cumplan con los requisitos legales establecidos para tal fin.", "Verificar las fichas prediales para cerciorarse que estén debidamente diligenciadas.", "Corregir las inconsistencias presentadas en el sistema computarizado, relacionadas con la información catastral, previa confrontación con los listados, para mantener la información actualizada.", "Administrar, controlar y conservar la información de la oficina, con la finalidad de tener respaldos y brindar atención oportuna a cada usuario relacionado con los predios catastrales.", "Verificar la liquidación de los avalúos de las zonas geoeconómicas de lotes acuerdo con las normas vigentes y calificar las construcciones para procurar unos ingresos reales.", "Aplicar los incrementos anuales decretados por el Gobierno Nacional, teniendo en cuenta si son predios municipales formados, para mantener actualizado el avalúo.", "Levantar los cambios físicos que se presenten en la propiedad inmueble del municipio, tanto en la zona urbana como rural.", "Presentar para su evaluación y seguimiento, informes sobre las actividades desarrolladas.", "Capacitar a la comunidad en los temas atinentes a su área.", "Asistir a las reuniones del consejo de gobierno, juntas y comités de los cuales haga parte o para los que se delegue.", "Adoptar, las acciones necesarias para garantizar el sistema de gestión de la calidad y el control interno dentro de la dependencia.", "Presentar, informes de gestión para hacer seguimiento y evaluación a los objetivos trazados por la dependencia.", "Apoyar al jefe de la dependencia en la elaboración de los planes de acción.", "Las demás que sean asignadas por el superior inmediato."]', 141 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=139 AND seccion='funciones');  -- FICHA 66
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 139, 'contribuciones', '["Información catastral actualizada y confiable  Mutaciones y cambios realizados de manera oportuna  Correcciones oportunas de las inconsistencias presentadas en la base de datos del catastro municipal  Monitoreo de verificación del diligenciamiento de las fichas de predial."]', 142 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=139 AND seccion='contribuciones');  -- FICHA 66
