INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 152, 'proposito', 'Apoyar la gestión de la Secretaría de tránsito y transporte, velando por que los diferentes tramites que se realicen, se ajusten a los procedimientos técnicos y normatividad legal vigente.', 140 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=152 AND seccion='proposito');  -- FICHA 41
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 152, 'funciones', '["Confrontar los datos de la información recibida y devolver a los usuarios los documentos fuentes cuando la información no cumpla con los requisitos estipulados.", "Recibir y revisar los documentos exigidos para cada uno de los trámites que se llevan a cabo en la secretaría, para garantizar eficiencia y eficacia en la prestación de los servicios.", "Velar por la conservación de las carpetas de los vehículos automotores, con el fin de salvaguardar la información contenida en ellas.", "Revisar los documentos previamente tramitados para el envío oportuno de éstos a la oficina de Tránsito elegida por el propietario, para garantizar el traslado de cuenta de vehículos automotores.", "Revisar el estado general, currículo y sistemas de identificación para autorizar traspasos, cambio de: color, motor, transformación, regrabación y legitimidad de los sistemas, entre otros, utilizando para ello los equipos necesarios.", "Archivar el proceso contravencional de acuerdo a las especificaciones dictadas en este evento y luego de haber cumplido con todos los pasos necesarios y estar firmado por el superior inmediato.", "Recepción de comparendos y radicarlos en libros de control.", "Liquidar comparendos que se generen en la dependencia.", "Elaborar ordenes de entrega de vehículos inmovilizados.", "Ingresar comparendos a la base de datos.", "Ingresar accidentes a la base de datos y generar archivos para el ministerio y   el fondo de prevención vial.", "Elaborar estadísticas de accidentalidad y comparendos.", "Descargare comparendos pagos.", "Responder derechos de petición interpuestos por prescripción.", "Elaborar reporte mensual a las empresas de conductores infractores.", "Generar archivos e informes del SIMIT.", "Imprimir resoluciones contravencionales de los distintos comparendos que se generen.", "Resolver, las consultas formuladas por los propietarios.", "Adoptar, las acciones necesarias para garantizar el sistema de gestión de la calidad y el control interno dentro de la dependencia.", "Y las demás que sean asignados por su jefe inmediato."]', 141 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=152 AND seccion='funciones');  -- FICHA 41
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 152, 'contribuciones', '["Procesos revisados al interior de la dependencia.", "Agilidad en los trámites realizados en la SECRETARÌA.", "La información generada en la dependencia, se conserva de conformidad con los procedimientos técnicos universalmente aceptados."]', 142 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=152 AND seccion='contribuciones');  -- FICHA 41
