INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 153, 'proposito', 'Administrar la información de la secretaria para personal interno y externo de conformidad con los procesos establecidos.', 140 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=153 AND seccion='proposito');  -- FICHA 42
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 153, 'funciones', '["Realizar las acciones necesarias que den cumplimiento a la solicitud de los diferentes tipos de servicio que tengan relación con la Secretaría. Enviar a los distintos estamentos gubernamentales los documentos que estos pudiesen solicitar y que tengan relación directa con sus funciones.", "Llevar el registro y control de los documentos y archivos de la oficina.", "Llevar el registro y control de ejecución de los contratos que estén bajo la Supervisión de la secretaría.", "Llevar el registro y control de los derechos de petición que se interpongan y que son de competencia de la dependencia, velando porque los mismos se contesten dentro de los plazos legalmente establecidos.", "Elaborar las solicitudes de servicio con su respectiva justificación. Mantener informe actualizado sobre la ejecución presupuestal de la dependencia  Realizar manejo de herramientas de sistemas, manipulación de bases de datos, revisión diaria y permanente del correo electrónico de la dependencia y generar las copias de los archivos que considere de interés para la Dependencia.", "Mantener actualizado el inventario de la dependencia.", "Realizar copias de seguridad sobre los archivos importantes de competencia de la secretaría y que se conserven en medio magnético.", "Apoyo al jefe de la dependencia en los trámites que se deban realizar para Garantizar el pago oportuno de los contratos a cargo de la secretaría. Lo anterior, en cuanto a la elaboración de actas de inicio, suspensión, de Terminación y de liquidación, informes de interventoría, certificados, etc.", "Elaborar resolución de viáticos y adelantar los trámites para la legalización de los mismos.", "Reportar de manera oportuna cualquier daño, deterioro, pérdida o anomalía en los equipos de oficina y bienes Cargados al inventario de la dependencia. Realizar uso racional de los recursos de la dependencia y colaborar con el jefe de la dependencia en las acciones de control que sobre el uso de esos mismos Bienes se implementen.", "Realizar labores de apoyo a los procesos administrativos que se ejecuten en la Secretaría de conformidad con los planes, programas y proyectos establecidos.", "Preparar los oficios, resoluciones, decretos, proyectos de acuerdo, actas y documentos en general en cumplimiento de los objetivos de la Secretaría para darles el respectivo trámite.", "Recibir, radicar y organizar la correspondencia para la firma del jefe y distribuirla de acuerdo con sus instrucciones.", "Llevar la agenda y recordar los compromisos.", "Atender personal y telefónicamente al público e informar al superior inmediato de los asuntos tratados.", "Recibir y confrontar que la documentación aportada por el usuario, cumpla los requisitos exigidos para legalizar él tramite solicitado o devolverlo si no los reúne, aclarando el motivo de dicha devolución.", "Tramitar los pedidos de útiles, papelería y demás elementos de oficina que se requieran en la dependencia.", "Adoptar, las acciones necesarias para garantizar el sistema de gestión de la calidad y el control interno dentro de la dependencia.", "Y las demás que sean asignados por el superior inmediato."]', 141 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=153 AND seccion='funciones');  -- FICHA 42
