INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 154, 'funciones', '["Llevar el registro y control de los documentos y archivos de la oficina.", "Llevar el registro y control de ejecución de los contratos que estén bajo la supervisión de la secretaría.", "Apoyo al jefe de la dependencia en los trámites que se deban realizar para garantizar el pago oportuno de los contratos a cargo de la secretaría. Lo anterior, en cuanto a la elaboración de actas de inicio, suspensión, de terminación y de liquidación, informes de interventoría, certificados, Etc.", "Elaborar resolución de viáticos y adelantar los trámites para la legalización de los mismos.", "Realizar labores de apoyo a los procesos administrativos y operativos, así como el desarrollo de programas y brigadas sociales que se ejecuten en la Secretaría de conformidad con los planes, programas y proyectos establecidos.", "Preparar los oficios, resoluciones, decretos, proyectos de acuerdo, actas y documentos en general en cumplimiento de los objetivos de la Secretaría para darles el respectivo trámite.", "Recibir, radicar y organizar la correspondencia para la firma del jefe y distribuirla de acuerdo con sus instrucciones.", "Atender personal y telefónicamente al público e informar al superior inmediato de los asuntos tratados.", "Elaborar las solicitudes de servicio con su respectiva justificación.", "Realizar un seguimiento para la correcta conservación de las carpetas de los vehículos automotores.", "Archivar los procesos contravencionales conforme a las especificaciones establecidas y los lineamientos del jefe inmediato.", "Asegurar que todos los documentos estén firmados y cumplidos con todos los pasos necesarios antes de ser archivados. Recibir los comparendos emitidos y radicarlos en los libros de control correspondientes. Apoyar en la elaboración de las órdenes de entrega de vehículos inmovilizados cuando se proceda a su liberación Ingresar los comparendos a la base de datos de acuerdo con el procedimiento establecido para su posterior seguimiento Apoyar en la generación de archivos e informes correspondientes al Sistema Integrado de Información sobre Movilidad (SIMIT). Apoyar en la impresión de resoluciones contravencionales derivadas de los comparendos generados. Resolver las consultas formuladas por los propietarios de vehículos, brindando información clara y precisa sobre el estado de sus trámites. Apoyar en las acciones necesarias para garantizar el cumplimiento del sistema de gestión de calidad y control interno en los procesos administrativos dentro de la dependencia Ejecutar las funciones adicionales que le sean asignadas por su jefe inmediato dentro del ámbito de sus responsabilidades y del servicio administrativo. Y las demás que sean asignados por su jefe inmediato."]', 141 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=154 AND seccion='funciones');  -- FICHA 43
