INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 155, 'proposito', 'Diseñar políticas de recuperación del sector agropecuario y medio ambiente, para la ejecución de los compromisos adquiridos en el Plan de Desarrollo Municipal.', 140 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=155 AND seccion='proposito');  -- FICHA 78
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 155, 'funciones', '["Fijar las políticas de la Secretaría, acorde con el Plan de Desarrollo Municipal a fin de dar cumplimiento a la misión institucional.", "Establecer las estrategias y el plan de acción a seguir para el logro de las políticas, programas y proyectos consagrados en el Plan de Desarrollo Municipal y liderar su ejecución.", "Supervisar la ejecución del presupuesto que corresponda a la Secretaría para controlar el gasto.", "Asistir ante el Concejo Municipal, juntas, comités y otros estamentos cuando le sean delegados por el señor Alcalde para que lo represente.", "Rendir informes periódicos al Alcalde y demás instituciones que lo requieran sobre el desarrollo y ejecución de los proyectos relacionados con las actividades de la Secretaría y/o la Administración central, para su correspondiente análisis, evaluación, seguimiento y toma de decisiones.", "Coordinar con la Secretaría de Planeación, los planes y programas de la Secretaría, tanto en su etapa de elaboración y formulación, para que sean inscritos en el Banco de Programas y Proyectos de Inversión Municipal.", "Gestionar ante las diferentes dependencias de la entidad o con organismos del orden Municipal, Departamental, subregional, Nacional e internacional, la obtención de los recursos necesarios, para asegurar el oportuno cumplimiento de los planes, programas y proyectos establecidos en el Plan de Desarrollo.", "Promover y ejecutar programas y políticas nacionales, regionales y sectoriales en relación con el medio ambiente y los recursos naturales renovables.", "Elaborar los planes, programas y proyectos ambientales municipales, articulados a los planes, programas y proyectos regionales, departamentales y nacionales.", "Dictar con sujeción a las disposiciones legales reglamentarias superiores, las normas necesarias para el control, la preservación y la defensa del patrimonio ecológico del municipio.", "Adoptar los planes, programas y proyectos de desarrollo ambiental y de los recursos    naturales renovables, que hayan sido discutidos y aprobados a nivel regional, conforme a las normas de planificación ambiental.", "Participar en la elaboración de planes, programas y proyectos de desarrollo ambiental y de los recursos naturales renovables a nivel departamental.", "Ejercer, a través del Alcalde, como primera autoridad de policía, con el apoyo de la Policía Nacional y en coordinación con las demás entidades del Sistema Nacional Ambiental (SINA), con sujeción a la distribución legal de competencias, funciones de control y vigilancia del medio ambiente y los recursos naturales renovables, con el fin de velar por el cumplimiento de los deberes del estado y de los particulares en materia ambiental y de proteger el derecho constitucional a un ambiente sano.", "Ejecutar obras o proyectos de descontaminación de corrientes o depósitos de agua afectados por vertimientos del municipio, así como programas de disposición final, eliminación y reciclaje de residuos líquidos y sólidos y de control a las emisiones contaminantes del aire.", "Detectar las necesidades de asistencia técnica agropecuaria en la jurisdicción del municipio.", "Desarrollar, coordinar y supervisar los programas tendientes al mejoramiento de explotaciones agrícolas y pecuarias de los pequeños productores, para contribuir al mejoramiento de la calidad de vida.", "Desarrollar proyectos de transferencia de tecnología para los beneficiarios en forma grupal de tal manera que permitan la difusión y aplicación de las recomendaciones tecnológicas apropiadas.", "Reglamentar los diferentes tipos de servicio que presta la institución a los beneficiarios de la asistencia técnica, para incrementar los recursos económicos y reinvertirlos en mejor prestación de los servicios.", "Sensibilizar a la comunidad en torno a las leyes, normas y elementos de tipo legal que soportan la defensa del medio ambiente, a través de talleres, seminarios, encuentros con usuarios del sector agropecuario, entre otros.", "Presentar iniciativas de proyectos de acuerdos, planes y programas al Alcalde en asuntos relacionados con la dependencia, para contribuir a la promoción del desarrollo social y participación equitativa de las comunidades rurales de bajos ingresos.", "Fomentar la participación ciudadana a través de los diferentes comités relacionados con su área.", "Fijar las políticas de la Secretaría, acordes con el Plan de Desarrollo Municipal, a fin de dar cumplimiento a la misión institucional.", "Establecer las estrategias y el plan de acción a seguir para el logro de las políticas, programas y proyectos consagradas en el Plan de Desarrollo Municipal y liderar su ejecución.", "Ejecutar políticas de normas, regionales y sectoriales en relación con el medio ambiente y recursos naturales renovables.", "Desarrollar proyectos para atacar las causas de degradación del medio ambiente y recursos naturales.", "Formular proyectos para mejorar la calidad de vida de los pequeños productores agropecuarios, aumentando su productividad y competitividad.", "Favorecer el desarrollo tecnológico del agro a través de la asistencia técnica y el apoyo social.", "Adoptar, las acciones necesarias para garantizar el sistema de gestión de la calidad y el control interno dentro de la dependencia."]', 141 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=155 AND seccion='funciones');  -- FICHA 78
INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 155, 'contribuciones', '["Políticas renovables, regionales y sectoriales ejecutables a través de Planes Programas y Proyectos.", "Formulación y desarrollo de programas y proyectos para atacar las causas de degradación del medio ambiente y recursos naturales.", "Ejecución de programas y proyectos que mejoran las condiciones de vida de los pequeños y medianos productores.", "Cumplimiento de las normas ambientales.", "Desarrollando medios tecnológicos del UAF (Unidad Agrícola Familiar), mediante la asistencia técnica prestada y el apoyo social brindado."]', 142 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=155 AND seccion='contribuciones');  -- FICHA 78
