INSERT INTO cargos_manual_detalle (cargo_manual_id, seccion, contenido, orden) SELECT 155, 'requisitos_estudio', 'ESTUDIOS Título profesional en disciplina académica del núcleo básico del conocimiento en: Agronomía, Medicina, Veterinaria, Zootecnia, Ingeniería Agrícola, forestal y afines, Ingeniería Ambiental, Sanitaria y afines, Ingeniería Agronómica, Ingeniería Agroindustrial.  Tarjeta profesional vigente en los casos exigidos por la ley.', 145 FROM (SELECT 1 AS one) AS d WHERE NOT EXISTS (SELECT 1 FROM cargos_manual_detalle WHERE cargo_manual_id=155 AND seccion='requisitos_estudio');  -- FICHA 78
